.c-accordion-demo {
  --accordion-accent: #b9f474;
  --accordion-accent-text: #162600;
  --accordion-border: #dcddd4;
  --accordion-border-strong: #bfc1b7;
  --accordion-canvas: #f5f5ef;
  --accordion-control-height: 2.75rem;
  --accordion-focus: #b9f474;
  --accordion-font: Inter, ui-sans-serif, system-ui, sans-serif;
  --accordion-muted: #62665d;
  --accordion-radius: 1rem;
  --accordion-surface: #ffffff;
  --accordion-text: #171915;

  align-content: center;
  background: var(--accordion-canvas);
  color: var(--accordion-text);
  display: grid;
  font-family: var(--accordion-font);
  min-height: 100%;
  padding: 2rem;
}

.c-accordion {
  background: var(--accordion-surface);
  border: 1px solid var(--accordion-border);
  border-radius: var(--accordion-radius);
  inline-size: min(100%, 42rem);
  margin-inline: auto;
  overflow: clip;
}

.c-accordion details {
  interpolate-size: allow-keywords;
}

.c-accordion details::details-content {
  block-size: 0;
  content-visibility: hidden;
  opacity: 0;
  overflow: clip;
  transition: block-size 180ms cubic-bezier(0.2, 0, 0, 1), content-visibility 180ms allow-discrete, opacity 180ms ease;
}

.c-accordion details[open]::details-content {
  block-size: auto;
  content-visibility: visible;
  opacity: 1;
}

.c-accordion details + details {
  border-block-start: 1px solid var(--accordion-border);
}

.c-accordion summary {
  align-items: center;
  cursor: pointer;
  display: flex;
  font-weight: 650;
  gap: 1rem;
  justify-content: space-between;
  line-height: 1.4;
  min-height: var(--accordion-control-height);
  padding: 1rem 1.5rem;
}

.c-accordion summary::-webkit-details-marker {
  display: none;
}

.c-accordion summary::after {
  align-items: center;
  background: var(--accordion-canvas);
  border-radius: 50%;
  content: "+";
  display: inline-flex;
  flex: 0 0 1.75rem;
  font-size: 1.25rem;
  font-weight: 400;
  height: 1.75rem;
  justify-content: center;
  line-height: 1;
  width: 1.75rem;
}

.c-accordion details[open] summary::after {
  background: var(--accordion-accent);
  color: var(--accordion-accent-text);
  content: "−";
}

.c-accordion summary:hover {
  background: var(--accordion-canvas);
}

.c-accordion summary:focus-visible {
  outline: 0.2rem solid var(--accordion-focus);
  outline-offset: -0.35rem;
}

.c-accordion__panel {
  color: var(--accordion-muted);
  line-height: 1.6;
  padding: 0 1.5rem 1.5rem;
}

.c-accordion__panel p {
  margin: 0;
}

@media (prefers-reduced-motion: reduce) {
  .c-accordion details::details-content {
    transition: none;
  }
}

@media (max-width: 32rem) {
  .c-accordion-demo {
    padding: 1rem;
  }

  .c-accordion summary {
    padding-inline: 1rem;
  }

  .c-accordion__panel {
    padding-inline: 1rem;
  }
}

