export interface AccordionController {
  open(index: number): void;
  close(index: number): void;
  destroy(): void;
}

export function createAccordion(root: HTMLElement): AccordionController {
  const items = [...root.querySelectorAll<HTMLDetailsElement>(':scope > [data-accordion-item]')];
  const summaries = items
    .map((item) => item.querySelector<HTMLElement>(':scope > summary'))
    .filter((summary): summary is HTMLElement => summary !== null);

  if (!items.length || summaries.length !== items.length) {
    throw new Error('Accordion markup is incomplete.');
  }

  const originalNames = items.map((item) => item.getAttribute('name'));
  const groupName = `accordion-${++accordionInstance}`;

  if (root.dataset['accordionMode'] !== 'multiple') {
    items.forEach((item) => item.setAttribute('name', groupName));
  }

  const handleKeydown = (event: KeyboardEvent): void => {
    const currentIndex = summaries.indexOf(event.target as HTMLElement);
    if (currentIndex < 0) return;

    let nextIndex = currentIndex;
    if (event.key === 'ArrowDown') nextIndex = (currentIndex + 1) % summaries.length;
    else if (event.key === 'ArrowUp') nextIndex = (currentIndex - 1 + summaries.length) % summaries.length;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = summaries.length - 1;
    else return;

    event.preventDefault();
    summaries[nextIndex]?.focus();
  };

  const handleToggle = (event: Event): void => {
    const item = event.currentTarget;
    if (!(item instanceof HTMLDetailsElement)) return;
    root.dispatchEvent(new CustomEvent('accordion:toggle', {
      detail: { index: items.indexOf(item), open: item.open }
    }));
  };

  root.addEventListener('keydown', handleKeydown);
  items.forEach((item) => item.addEventListener('toggle', handleToggle));

  return {
    open(index: number): void {
      const item = items[index];
      if (item) item.open = true;
    },
    close(index: number): void {
      const item = items[index];
      if (item) item.open = false;
    },
    destroy(): void {
      root.removeEventListener('keydown', handleKeydown);
      items.forEach((item, index) => {
        item.removeEventListener('toggle', handleToggle);
        const originalName = originalNames[index];
        if (originalName === null) item.removeAttribute('name');
        else if (originalName !== undefined) item.setAttribute('name', originalName);
      });
    }
  };
}

document.querySelectorAll<HTMLElement>('[data-component="accordion"]').forEach(createAccordion);

